package com.example.starter.map;

/**
 * 地图路段领域对象：端点拓扑 + 直线几何 + 有效状态。
 *
 * @param segmentId 路段业务标识，版本内唯一
 * @param startNode 起点拓扑节点标识
 * @param endNode   终点拓扑节点标识
 * @param startX    起点坐标 X，单位米
 * @param startY    起点坐标 Y，单位米
 * @param endX      终点坐标 X，单位米
 * @param endY      终点坐标 Y，单位米
 * @param active    有效状态；false 表示已失效，不参与候选匹配
 */
public record MapSegment(
        String segmentId,
        String startNode,
        String endNode,
        double startX,
        double startY,
        double endX,
        double endY,
        boolean active) {

    /**
     * 路段航向角，单位度，范围 [0,360)。
     */
    public double headingDegrees() {
        double deg = Math.toDegrees(Math.atan2(endY - startY, endX - startX));
        return (deg + 360.0) % 360.0;
    }
}

package com.example.starter.map;

/**
 * 地图版本状态：ACTIVE=可服务；DEPRECATED=已废弃（不接受新请求，已绑定请求仍可回放）。
 */
public enum MapVersionStatus {
    ACTIVE,
    DEPRECATED
}

package com.example.starter.map;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 地图版本视图：版本元信息 + 全量路段快照。版本发布后内容不可变。
 *
 * @param versionId  地图版本业务标识
 * @param status     版本状态
 * @param segments   版本内全部路段
 * @param createdAt  发布时间（Asia/Shanghai）
 */
public record MapVersionView(
        String versionId,
        MapVersionStatus status,
        List<MapSegment> segments,
        LocalDateTime createdAt) {
}

