package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 路段发布输入。
 *
 * @param segmentId 路段业务标识，版本内唯一
 * @param startNode 起点拓扑节点标识
 * @param endNode   终点拓扑节点标识
 * @param startX    起点坐标 X，单位米
 * @param startY    起点坐标 Y，单位米
 * @param endX      终点坐标 X，单位米
 * @param endY      终点坐标 Y，单位米
 * @param active    有效状态
 */
public record SegmentDto(
        @NotBlank String segmentId,
        @NotBlank String startNode,
        @NotBlank String endNode,
        double startX,
        double startY,
        double endX,
        double endY,
        boolean active) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

import java.util.List;

/**
 * 地图版本发布请求；发布即不可变，热更新只能再发布新版本。
 *
 * @param versionId 地图版本业务标识，全局唯一
 * @param segments  版本内全部路段，至少一条
 */
public record PublishMapVersionRequest(
        @NotBlank String versionId,
        @NotEmpty List<SegmentDto> segments) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;

/**
 * 匹配输入点。
 *
 * @param x       坐标 X，单位米
 * @param y       坐标 Y，单位米
 * @param heading 航向角，单位度，范围 [0,360)
 */
public record PointDto(
        double x,
        double y,
        @DecimalMin("0") @DecimalMax(value = "360", inclusive = false) double heading) {
}

package com.example.starter.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 路线请求提交入参；requestId 为幂等键，请求固定绑定一个明确地图版本。
 *
 * @param requestId    请求业务标识
 * @param mapVersionId 明确绑定的地图版本标识
 * @param origin       起点匹配输入
 * @param destination  终点匹配输入
 */
public record SubmitRouteRequest(
        @NotBlank String requestId,
        @NotBlank String mapVersionId,
        @NotNull @Valid PointDto origin,
        @NotNull @Valid PointDto destination) {
}

package com.example.starter.web.dto;

import com.example.starter.match.MatchResult;

/**
 * 路线请求响应。
 *
 * @param requestId    请求业务标识
 * @param mapVersionId 请求固定绑定的地图版本
 * @param status       SUCCESS 或 FAILED
 * @param errorCode    失败错误码；成功时为 null
 * @param result       匹配结果快照；失败时为 null
 */
public record RouteResponse(
        String requestId,
        String mapVersionId,
        String status,
        String errorCode,
        MatchResult result) {
}

