    def workerJar = new File(gradle.gradleUserHomeDir, 'caches/8.14.4/workerMain/gradle-worker.jar')
    println "DIAG workerJar exists=${workerJar.exists()} path=$workerJar"
    def javaExe = System.getProperty('java.home') + File.separator + 'bin' + File.separator + 'java.exe'
    def mainClass = 'worker.org.gradle.process.internal.worker.GradleWorkerMain'
    def diagDir = new File(buildDir, 'diag')
    diagDir.mkdirs()

    // 变体1：classpath jar（manifest Class-Path 指向中文路径 jar）
    def cpJar = new File(diagDir, 'cp.jar')
    def manifest = new java.util.jar.Manifest()
    manifest.mainAttributes.putValue('Manifest-Version', '1.0')
    manifest.mainAttributes.putValue('Class-Path', workerJar.toURI().toURL().toString())
    def jos = new java.util.jar.JarOutputStream(new FileOutputStream(cpJar), manifest)
    jos.close()
    ['plain-cp': [javaExe, '-cp', workerJar.absolutePath, mainClass],
     'classpath-jar': [javaExe, '-cp', cpJar.absolutePath, mainClass]
    ].each { name, cmd ->
        def pb = new ProcessBuilder(cmd)
        pb.redirectErrorStream(true)
        def proc = pb.start()
        proc.outputStream.close()
        def output = proc.inputStream.getText('GBK')
        proc.waitFor()
        def firstLine = output.readLines().find { it.trim() } ?: '(no output)'
        println "DIAG [$name] exit=${proc.exitValue()} first=${firstLine.take(200)}"
    }

    // 变体2/3：argfile（UTF-8 与 GBK 两种编码写入中文类路径）
    ['utf-8', 'gbk'].each { enc ->
        def argFile = new File(diagDir, "args-${enc}.txt")
        argFile.setText("-cp \"${workerJar.absolutePath}\"", enc)
        def pb = new ProcessBuilder(javaExe, "@${argFile.absolutePath}", mainClass)
        pb.redirectErrorStream(true)
        def proc = pb.start()
        proc.outputStream.close()
        def output = proc.inputStream.getText('GBK')
        proc.waitFor()
        def firstLine = output.readLines().find { it.trim() } ?: '(no output)'
        println "DIAG [argfile-$enc] exit=${proc.exitValue()} first=${firstLine.take(200)}"
    }
}

